head.script:
let curRowIndex = null;
let oldRowIndex = null;



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > rowNumRowMouseOverColor]<br/>마우스 포인터가 Body 영역의 Row 에 오버될때 RowNum Cell 의 배경색을 유지할지 설정합니다.",
    "validation" : [
        "rowNumVisible='true', rowMouseOver='true' 인 경우에 동작합니다.",
        "미설정 또는 true 설정 시 Body 영역 Row 에 마우스 포인터가 오버되면 RowNum Cell 에 rowMouseOverColor 속성의 배경색이 적용됩니다.",
        "--- 해당 Row 의 마우스 오버가 해제되면 RowNum Cell 에 rowNumBackgroundColor 속성의 배경색이 다시 적용됩니다.",
        "false 설정 시 Body 영역 Row 에 마우스 포인터가 오버되어도 RowNum Cell 의 배경색은 변경되지 않습니다.",
        "--- RowNum Cell 에 rowNumBackgroundColor 속성의 배경색이 유지됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }    

    // 조건 설정   
    let properties = {
        rowNumRowMouseOverColor: con_rowNumRowMouseOverColor.getText(),
        rowMouseOver: true,        
        rowNumVisible: true,      
        rowMouseOverColor: "#777777",        
        dataList: "data:dlt_bind",      
    };

    let cList = $c.gcm.createCList(properties);      
    let eList = $c.gcm.createEList(["onbodymouseover"]);

    // dataList 생성
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성   
    $c.gcm.createBasicGridView(cList, eList);

    curRowIndex = null;
    oldRowIndex = null;
}



scwin.btn_rowNumBackgroundColor_onclick = function (curRowIndex) {  
    if (curRowIndex !== oldRowIndex ) {  
        let targetElement = document.querySelector('td[id*="target1_headerRowNumber_bodyRow_'+curRowIndex+'"]');

        if (targetElement) {
            let style = window.getComputedStyle(targetElement);
            let backgroundColor = style.backgroundColor;

            wf_body_bottom.getObj("scwin").setReturnValue("backgroundColor : " + backgroundColor);	            
        }
    }

    oldRowIndex = curRowIndex;
}



scwin.target1_onbodymouseover = function (info) {
    curRowIndex = info.rowIndex;

    scwin.btn_rowNumBackgroundColor_onclick(curRowIndex);
}
